# Manifest for the correction round. c1 exited before writing: node26 is a .cmd.
# Do not edit this file after it runs.
# Usage: python -I work/scripts/write_manifest_c2.py NN
# NN is this command. Its .out, .err and .exit do not exist yet.
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

if len(sys.argv) != 2 or not re.fullmatch(r'\d+', sys.argv[1]):
    sys.stderr.write('usage: python -I work/scripts/write_manifest_c2.py NN\n')
    sys.exit(2)
SELF = f'{int(sys.argv[1]):02d}'
SELF_EXIT = Path(f'work/out/cmd/{SELF}.exit')
SELF_CMD = Path(f'work/out/cmd/{SELF}.cmd.txt')
if SELF_EXIT.exists():
    sys.stderr.write(f'{SELF}.exit already exists; this writer must be that command\n')
    sys.exit(2)

ROOT = Path('.').resolve()
RESEARCH = [
    'TASK.md',
    'brief.md',
    'templates/result.md',
    'audit/previous-review.md',
    'ref/tasks/T3j-afon-acceptance-assertions/brief.md',
    'ref/tasks/T3j-afon-acceptance-assertions/decision.md',
    'ref/analysis/button-af/readiness/t3-afon-zone-row/design/T3i-design.md',
    'ref/analysis/button-af/readiness/t3-afon-zone-row/README.md',
    'ref/analysis/button-af/AFON-MENU-RESEARCH.md',
    'ref/AF-PROFILE-PROTOTYPE.md',
    'ref/scripts/om_emu_af_edge_overlay.py',
    'ref/scripts/om_emu_af_live_probe.mjs',
    'ref/analysis/button-af/readiness/om-emu-af-native1/central-edge-v2.csv',
    'ref/analysis/button-af/readiness/om-emu-af-native1/central-edge-v2.json',
    'ref/analysis/button-af/readiness/task-context-placement1/live-profile-relocation-map.txt',
]
CONSUMED = [
    'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/out/overlay-changed-bytes.csv',
    'ref/tasks/T3j-afon-acceptance-assertions/run-20261118-132500/work/scripts/accept_table_j1.json',
    'ref/analysis/button-af/readiness/t3-afon-zone-row/t3j/overlay-changed-bytes.csv',
]


def rel(path):
    s = str(path).replace('\\', '/')
    root = str(ROOT).replace('\\', '/')
    if s.lower().startswith(root.lower() + '/'):
        s = s[len(root) + 1:]
    return s


def sha_file(path):
    data = Path(path).read_bytes()
    return hashlib.sha256(data).hexdigest(), len(data)


def tool(args):
    try:
        return subprocess.check_output(args, text=True, stderr=subprocess.STDOUT).strip()
    except Exception as e:
        return str(e)


def add_exec(store, path, digest, nbytes, where):
    key = rel(path)
    recorded = None
    if not Path(key).is_file():
        candidate = Path('work/scripts') / Path(key).name
        if candidate.is_file():
            later, n = sha_file(candidate)
            if later == digest and (nbytes is None or n == nbytes):
                recorded = key
                key = rel(candidate)
                if nbytes is None:
                    nbytes = n
    row = store.setdefault(key, {'sha256': digest, 'bytes': nbytes, 'where': []})
    if row['sha256'] != digest or (nbytes is not None and row['bytes'] not in (None, nbytes)):
        row.setdefault('conflicts', []).append({'sha256': digest, 'bytes': nbytes, 'where': where})
    elif row['bytes'] is None and nbytes is not None:
        row['bytes'] = nbytes
    row['where'].append(where)
    if recorded:
        got = row.setdefault('recorded_paths', [])
        if recorded not in got:
            got.append(recorded)


exec_hashes = {}
for inventory_path in sorted(Path('work/out').glob('import-inventory-*.json')):
    inventory = json.loads(inventory_path.read_text(encoding='utf-8'))
    for item in inventory.get('modules', []) + inventory.get('resources', []):
        add_exec(exec_hashes, item['path'], item['sha256'], item['bytes'], rel(inventory_path))

for path in sorted(Path('work/out').rglob('*.jsonl')):
    text = path.read_text(encoding='utf-8')
    if '"helper-hashes"' not in text:
        continue
    for line in text.splitlines():
        if '"helper-hashes"' not in line:
            continue
        rec = json.loads(line)
        if rec.get('step') != 'helper-hashes':
            continue
        where = rel(path) + '#helper-hashes'
        for item in rec.get('helpers', []) + rec.get('resources', []):
            add_exec(exec_hashes, item['path'], item['sha256'], item.get('bytes'), where)

for exit_path in sorted(Path('work/out/cmd').glob('*.exit'), key=lambda p: int(p.name.split('.')[0])):
    doc = json.loads(exit_path.read_text(encoding='utf-8'))
    for item in doc.get('scripts') or []:
        add_exec(exec_hashes, item['path'], item['sha256'], item.get('bytes'), rel(exit_path))

if SELF_CMD.is_file():
    cmd_text = SELF_CMD.read_text(encoding='utf-8')
    blocks = re.findall(
        r'script: (.+)\nscript_sha256: ([0-9a-f]+)\nscript_bytes: (\d+)',
        cmd_text,
    )
    for path, digest, nbytes in blocks:
        if path == 'none':
            continue
        add_exec(exec_hashes, path, digest, int(nbytes), rel(SELF_CMD))
    wrap = re.search(r'wrapper_sha256: ([0-9a-f]+)', cmd_text)
    if wrap:
        add_exec(exec_hashes, 'work/scripts/run_logged.mjs', wrap.group(1), None, rel(SELF_CMD))

for cmd_path in sorted(Path('work/out/cmd').glob('*.cmd.txt'), key=lambda p: int(p.name.split('.')[0])):
    if cmd_path == SELF_CMD:
        continue
    text = cmd_path.read_text(encoding='utf-8')
    wrap = re.search(r'wrapper_sha256: ([0-9a-f]+)', text)
    if wrap:
        add_exec(exec_hashes, 'work/scripts/run_logged.mjs', wrap.group(1), None, rel(cmd_path))

inputs = []
seen = set()
for key, rec in sorted(exec_hashes.items()):
    if key.startswith('work/'):
        continue
    if not Path(key).is_file():
        inputs.append({
            'path': key,
            'sha256': rec['sha256'],
            'bytes': rec['bytes'],
            'hashed': 'execution',
            'execution_where': rec['where'],
            'later_matches': None,
            'recorded_paths': rec.get('recorded_paths', []),
            'note': 'wrapper recorded a path that is not a file in this folder',
        })
        seen.add(key)
        continue
    later, nbytes = sha_file(key)
    inputs.append({
        'path': key,
        'sha256': rec['sha256'],
        'bytes': rec['bytes'],
        'hashed': 'execution',
        'execution_where': rec['where'],
        'later_sha256': later,
        'later_matches': later == rec['sha256'] and (rec['bytes'] is None or nbytes == rec['bytes']),
        'conflicts': rec.get('conflicts', []),
        'recorded_paths': rec.get('recorded_paths', []),
    })
    seen.add(key)

for path in RESEARCH + CONSUMED:
    if not Path(path).is_file():
        sys.stderr.write('missing consumed or research file: ' + path + '\n')
        sys.exit(2)
    if rel(path) in seen:
        continue
    digest, nbytes = sha_file(path)
    inputs.append({'path': rel(path), 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'})
    seen.add(rel(path))

sources = []
for path in sorted(Path('work/scripts').glob('*')):
    if not path.is_file():
        continue
    digest, nbytes = sha_file(path)
    key = rel(path)
    row = {'path': key, 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'}
    if key in exec_hashes:
        rec = exec_hashes[key]
        row['hashed'] = 'execution'
        row['execution_sha256'] = rec['sha256']
        row['execution_where'] = rec['where']
        row['later_matches'] = digest == rec['sha256'] and (rec['bytes'] is None or nbytes == rec['bytes'])
        row['conflicts'] = rec.get('conflicts', [])
        row['recorded_paths'] = rec.get('recorded_paths', [])
    sources.append(row)

outputs = []
out_files = [Path('work/result.md')]
out_files.extend(p for p in Path('work/out').rglob('*') if p.is_file())
for path in sorted(out_files, key=lambda p: rel(p)):
    digest, nbytes = sha_file(path)
    outputs.append({'path': rel(path), 'sha256': digest, 'bytes': nbytes, 'hashed': 'later'})

commands = []
present = []
for exit_path in sorted(Path('work/out/cmd').glob('*.exit'), key=lambda p: int(p.name.split('.')[0])):
    doc = json.loads(exit_path.read_text(encoding='utf-8'))
    n = exit_path.name.split('.')[0]
    present.append(n)
    row = {
        'id': n,
        'spawn': doc.get('spawn'),
        'status': doc.get('status'),
        'start': doc.get('start'),
        'end': doc.get('end'),
        'hashed': 'later',
    }
    for suffix, key in (
        ('cmd.txt', 'cmd_file'),
        ('out', 'out_file'),
        ('err', 'err_file'),
        ('exit', 'exit_file'),
    ):
        file_path = Path(f'work/out/cmd/{n}.{suffix}')
        if file_path.is_file():
            row[key] = rel(file_path)
    commands.append(row)

expected = [f'{i:02d}' for i in range(1, int(SELF))]
missing = [n for n in expected if n not in present]
self_row = {
    'id': SELF,
    'spawn': f'python -I work/scripts/write_manifest_c2.py {int(SELF)}',
    'status': None,
    'hashed': 'later',
    'note': (
        f'This process is command {SELF}. The wrapper writes work/out/cmd/{SELF}.out, '
        f'work/out/cmd/{SELF}.err and work/out/cmd/{SELF}.exit after the manifest is closed, '
        f'so those three files are not entries above. work/out/cmd/{SELF}.cmd.txt is written '
        f'before this process starts.'
    ),
}
if SELF_CMD.is_file():
    self_row['cmd_file'] = rel(SELF_CMD)
commands.append(self_row)

brief_sha, _ = sha_file('brief.md')
manifest = {
    'task': 'T5',
    'brief_sha256': brief_sha,
    'brief_hashed': 'later',
    'inputs': inputs,
    'sources': sources,
    'outputs': outputs,
    'commands': commands,
    'tool_versions': {
        'node26': tool(['cmd.exe', '/d', '/c', 'node26 --version']),
        'python': tool(['python', '--version']),
    },
    'note': (
        'Execution hashes of emulator modules come from every work/out/import-inventory-*.json '
        'and from session helper-hashes. Script hashes come from each completed NN.exit, and from '
        f'work/out/cmd/{SELF}.cmd.txt for this process. A wrapper path that is not a file is resolved '
        'to work/scripts/<name> when the bytes match; DisasmRangesK1.java resolves that way. '
        'Command 41.out, 41.err and 41.exit are included with the other completed command files. '
        f'The manifest file itself is not an output entry. Command {SELF} .out, .err and .exit are '
        'written after this file closes. The profile byte is RAM only. No firmware image was written. '
        'Subject Detect stayed Off. Native placement of the three section-7 call-site bytes is a T4 question.'
    ),
}
if missing:
    manifest['missing_commands'] = missing

Path('work/evidence-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
bad = []
for row in inputs + sources:
    if row.get('later_matches') is False or row.get('conflicts') or row.get('later_matches') is None and row.get('hashed') == 'execution':
        bad.append(row['path'])
print('inputs', len(inputs), 'sources', len(sources), 'outputs', len(outputs), 'commands', len(commands))
print('missing_commands', missing)
print('mismatches', bad)
if bad or missing:
    sys.exit(1)
